CREATE TABLE `customer_recovery_rules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `rule` ENUM('INACTIVE','CANCELED_NO_REBOOK','NO_SHOW_NO_REBOOK','POST_SERVICE_NO_RETURN','BIRTHDAY') NOT NULL, `active` BOOLEAN NOT NULL DEFAULT TRUE, `days` INT NOT NULL DEFAULT 30, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `customer_recovery_rules_public_id_key` (`public_id`), UNIQUE INDEX `customer_recovery_rules_tenant_id_rule_key` (`tenant_id`,`rule`), CONSTRAINT `customer_recovery_rules_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO `customer_recovery_rules` (`public_id`,`tenant_id`,`rule`,`active`,`days`) SELECT UUID(), `id`, 'INACTIVE', FALSE, 90 FROM `tenants` UNION ALL SELECT UUID(), `id`, 'CANCELED_NO_REBOOK', FALSE, 7 FROM `tenants` UNION ALL SELECT UUID(), `id`, 'NO_SHOW_NO_REBOOK', FALSE, 7 FROM `tenants` UNION ALL SELECT UUID(), `id`, 'POST_SERVICE_NO_RETURN', FALSE, 30 FROM `tenants` UNION ALL SELECT UUID(), `id`, 'BIRTHDAY', FALSE, 1 FROM `tenants`;
CREATE TABLE `customer_recovery_executions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `rule_id` BIGINT UNSIGNED NOT NULL, `customer_id` BIGINT UNSIGNED NOT NULL, `period_key` VARCHAR(64) NOT NULL, `status` ENUM('SENT','SKIPPED','FAILED') NOT NULL DEFAULT 'SENT', `error` VARCHAR(500) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `customer_recovery_executions_public_id_key` (`public_id`), UNIQUE INDEX `customer_recovery_executions_rule_id_customer_id_period_key_key` (`rule_id`,`customer_id`,`period_key`), CONSTRAINT `customer_recovery_executions_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `customer_recovery_executions_rule_id_fkey` FOREIGN KEY (`rule_id`) REFERENCES `customer_recovery_rules`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `customer_recovery_executions_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
